<?php
function communicationSchema(PDO $pdo){
    $pdo->exec("CREATE TABLE IF NOT EXISTS aurora_internal_messages (id BIGINT UNSIGNED NOT NULL AUTO_INCREMENT PRIMARY KEY,sender_system VARCHAR(8) NOT NULL,sender_user_id BIGINT UNSIGNED NOT NULL,recipient_system VARCHAR(8) NOT NULL,recipient_user_id BIGINT UNSIGNED NOT NULL,content TEXT NOT NULL,topic_tag VARCHAR(80) NULL,reply_to_id BIGINT UNSIGNED NULL,message_type VARCHAR(16) NOT NULL DEFAULT 'text',read_at DATETIME NULL,created_at DATETIME NOT NULL,updated_at DATETIME NOT NULL,INDEX idx_message_sender(sender_system,sender_user_id,created_at),INDEX idx_message_recipient(recipient_system,recipient_user_id,read_at,created_at)) ENGINE=InnoDB DEFAULT CHARSET=utf8 COLLATE=utf8_unicode_ci");
    foreach(['reply_to_id'=>"BIGINT UNSIGNED NULL AFTER topic_tag",'message_type'=>"VARCHAR(16) NOT NULL DEFAULT 'text' AFTER reply_to_id",'group_id'=>"BIGINT UNSIGNED NULL AFTER recipient_user_id"] as $name=>$definition){$q=$pdo->query("SHOW COLUMNS FROM aurora_internal_messages LIKE ".$pdo->quote($name));if(!$q->fetch())$pdo->exec("ALTER TABLE aurora_internal_messages ADD COLUMN {$name} {$definition}");}
    $pdo->exec("CREATE TABLE IF NOT EXISTS aurora_message_attachments (id BIGINT UNSIGNED NOT NULL AUTO_INCREMENT PRIMARY KEY,message_id BIGINT UNSIGNED NOT NULL,original_name VARCHAR(255) NOT NULL,stored_name VARCHAR(255) NOT NULL,mime_type VARCHAR(120) NOT NULL,size_bytes BIGINT UNSIGNED NOT NULL,created_at DATETIME NOT NULL,UNIQUE KEY uq_attachment_message(message_id),INDEX idx_attachment_message(message_id)) ENGINE=InnoDB DEFAULT CHARSET=utf8 COLLATE=utf8_unicode_ci");
    $pdo->exec("CREATE TABLE IF NOT EXISTS aurora_message_reactions (message_id BIGINT UNSIGNED NOT NULL,actor_system VARCHAR(8) NOT NULL,actor_user_id BIGINT UNSIGNED NOT NULL,emoji VARCHAR(16) NOT NULL,created_at DATETIME NOT NULL,PRIMARY KEY(message_id,actor_system,actor_user_id,emoji),INDEX idx_reaction_message(message_id)) ENGINE=InnoDB DEFAULT CHARSET=utf8 COLLATE=utf8_unicode_ci");
    $pdo->exec("CREATE TABLE IF NOT EXISTS aurora_chat_groups (id BIGINT UNSIGNED NOT NULL AUTO_INCREMENT PRIMARY KEY,name VARCHAR(80) NOT NULL,description VARCHAR(240) NULL,created_by_system VARCHAR(8) NOT NULL,created_by_user_id BIGINT UNSIGNED NOT NULL,created_at DATETIME NOT NULL,updated_at DATETIME NOT NULL) ENGINE=InnoDB DEFAULT CHARSET=utf8 COLLATE=utf8_unicode_ci");
    $pdo->exec("CREATE TABLE IF NOT EXISTS aurora_chat_group_members (group_id BIGINT UNSIGNED NOT NULL,member_system VARCHAR(8) NOT NULL,member_user_id BIGINT UNSIGNED NOT NULL,member_role VARCHAR(16) NOT NULL DEFAULT 'member',joined_at DATETIME NOT NULL,left_at DATETIME NULL,PRIMARY KEY(group_id,member_system,member_user_id),INDEX idx_group_member(member_system,member_user_id,left_at)) ENGINE=InnoDB DEFAULT CHARSET=utf8 COLLATE=utf8_unicode_ci");
    $pdo->exec("CREATE TABLE IF NOT EXISTS aurora_chat_group_reads (group_id BIGINT UNSIGNED NOT NULL,member_system VARCHAR(8) NOT NULL,member_user_id BIGINT UNSIGNED NOT NULL,last_read_message_id BIGINT UNSIGNED NOT NULL DEFAULT 0,read_at DATETIME NOT NULL,PRIMARY KEY(group_id,member_system,member_user_id)) ENGINE=InnoDB DEFAULT CHARSET=utf8 COLLATE=utf8_unicode_ci");
}
function communicationReactionCodes(){return ['👍'=>'like','❤️'=>'heart','😂'=>'laugh','😮'=>'wow','😢'=>'sad','🎉'=>'celebrate'];}
function communicationUploadDir(){return dirname(dirname(__DIR__)).DIRECTORY_SEPARATOR.'uploads'.DIRECTORY_SEPARATOR.'communications';}
function communicationPartner($value){if(!preg_match('/^(ems|tms|group):(\d+)$/',(string)$value,$m))jsonResponse(['status'=>'error','message'=>'Cuộc trò chuyện không hợp lệ.'],422);return [$m[1],intval($m[2])];}
function communicationThreadSql(){return "((m.sender_system='ems' AND m.sender_user_id=? AND m.recipient_system=? AND m.recipient_user_id=?) OR (m.sender_system=? AND m.sender_user_id=? AND m.recipient_system='ems' AND m.recipient_user_id=?))";}
function handleEmsCommunications(PDO $pdo,$route,$method,$body){
    communicationSchema($pdo);$input=array_merge(is_array($body)?$body:[],$_POST);$emsId=intval($_GET['user_id']??($input['user_id']??0));$q=$pdo->prepare("SELECT id,name,role FROM ems_users WHERE id=? AND status='active' LIMIT 1");$q->execute([$emsId]);$me=$q->fetch();if(!$me)jsonResponse(['status'=>'error','message'=>'Tài khoản EMS không hợp lệ.'],401);
    if($route==='/communications/contacts'&&$method==='GET'){$contacts=[];foreach($pdo->query("SELECT id,name,role,email,department,avatar FROM ems_users WHERE status='active' ORDER BY name") as $x){if(intval($x['id'])===$emsId)continue;$x['system']='ems';$x['ref']='ems:'.$x['id'];$contacts[]=$x;}foreach($pdo->query("SELECT id,full_name AS name,role,email,theater_id FROM users WHERE status='active' AND role<>'customer' ORDER BY full_name") as $x){$x['system']='tms';$x['ref']='tms:'.$x['id'];$x['department']='Theater Management System';$contacts[]=$x;}$q=$pdo->prepare("SELECT IF(sender_system='ems' AND sender_user_id=?,CONCAT(recipient_system,':',recipient_user_id),CONCAT(sender_system,':',sender_user_id)) ref,MAX(id) last_id FROM aurora_internal_messages WHERE group_id IS NULL AND ((sender_system='ems' AND sender_user_id=?) OR (recipient_system='ems' AND recipient_user_id=?)) GROUP BY ref ORDER BY last_id DESC");$q->execute([$emsId,$emsId,$emsId]);$refs=array_column($q->fetchAll(),'ref');$q=$pdo->prepare("SELECT g.id,g.name,g.description,COUNT(all_members.member_user_id) member_count FROM aurora_chat_groups g JOIN aurora_chat_group_members mine ON mine.group_id=g.id AND mine.member_system='ems' AND mine.member_user_id=? AND mine.left_at IS NULL JOIN aurora_chat_group_members all_members ON all_members.group_id=g.id AND all_members.left_at IS NULL GROUP BY g.id ORDER BY g.updated_at DESC");$q->execute([$emsId]);foreach($q as $g){$g['system']='group';$g['ref']='group:'.$g['id'];$g['role']='group';$g['department']=$g['description']?:($g['member_count'].' thành viên');$contacts[]=$g;array_unshift($refs,$g['ref']);}$q=$pdo->prepare("SELECT CONCAT(sender_system,':',sender_user_id) ref,COUNT(*) total FROM aurora_internal_messages WHERE recipient_system='ems' AND recipient_user_id=? AND read_at IS NULL GROUP BY sender_system,sender_user_id");$q->execute([$emsId]);$unread=[];foreach($q as $x)$unread[$x['ref']]=intval($x['total']);jsonResponse(['status'=>'success','data'=>['contacts'=>$contacts,'conversation_refs'=>array_values(array_unique($refs)),'unread'=>$unread]]);}
    if($route==='/communications/files'&&$method==='GET'){$fileId=intval($_GET['id']??0);$q=$pdo->prepare("SELECT a.* FROM aurora_message_attachments a JOIN aurora_internal_messages m ON m.id=a.message_id JOIN aurora_chat_group_members gm ON gm.group_id=m.group_id AND gm.member_system='ems' AND gm.member_user_id=? AND gm.left_at IS NULL WHERE a.id=? LIMIT 1");$q->execute([$emsId,$fileId]);if($x=$q->fetch()){$path=communicationUploadDir().DIRECTORY_SEPARATOR.$x['stored_name'];if(!is_file($path))jsonResponse(['status'=>'error','message'=>'Tệp không còn tồn tại.'],404);header('Content-Type: '.$x['mime_type']);header('Content-Length: '.filesize($path));header("Content-Disposition: attachment; filename*=UTF-8''".rawurlencode(basename($x['original_name'])));readfile($path);exit;}}
    if($route==='/communications/files'&&$method==='GET'){$id=intval($_GET['id']??0);$q=$pdo->prepare("SELECT a.* FROM aurora_message_attachments a JOIN aurora_internal_messages m ON m.id=a.message_id WHERE a.id=? AND ((m.sender_system='ems' AND m.sender_user_id=?) OR (m.recipient_system='ems' AND m.recipient_user_id=?)) LIMIT 1");$q->execute([$id,$emsId,$emsId]);$x=$q->fetch();if(!$x)jsonResponse(['status'=>'error','message'=>'Không tìm thấy tệp hoặc bạn không có quyền tải.'],404);$path=communicationUploadDir().DIRECTORY_SEPARATOR.$x['stored_name'];if(!is_file($path))jsonResponse(['status'=>'error','message'=>'Tệp không còn tồn tại.'],404);$name=str_replace(["\r","\n",'"'],'',basename($x['original_name']));header('Content-Type: '.$x['mime_type']);header('Content-Length: '.filesize($path));header("Content-Disposition: attachment; filename*=UTF-8''".rawurlencode($name));readfile($path);exit;}
    if($route==='/communications/contacts'&&$method==='GET'){$contacts=[];foreach($pdo->query("SELECT id,name,role,email,department,avatar FROM ems_users WHERE status='active' ORDER BY name") as $x){if(intval($x['id'])===$emsId)continue;$x['system']='ems';$x['ref']='ems:'.$x['id'];$contacts[]=$x;}foreach($pdo->query("SELECT id,full_name AS name,role,email,theater_id FROM users WHERE status='active' AND role<>'customer' ORDER BY full_name") as $x){$x['system']='tms';$x['ref']='tms:'.$x['id'];$x['department']='Theater Management System';$contacts[]=$x;}$q=$pdo->prepare("SELECT IF(sender_system='ems' AND sender_user_id=?,CONCAT(recipient_system,':',recipient_user_id),CONCAT(sender_system,':',sender_user_id)) ref,MAX(id) last_id FROM aurora_internal_messages WHERE (sender_system='ems' AND sender_user_id=?) OR (recipient_system='ems' AND recipient_user_id=?) GROUP BY ref ORDER BY last_id DESC");$q->execute([$emsId,$emsId,$emsId]);$refs=array_column($q->fetchAll(),'ref');$q=$pdo->prepare("SELECT CONCAT(sender_system,':',sender_user_id) ref,COUNT(*) total FROM aurora_internal_messages WHERE recipient_system='ems' AND recipient_user_id=? AND read_at IS NULL GROUP BY sender_system,sender_user_id");$q->execute([$emsId]);$unread=[];foreach($q as $x)$unread[$x['ref']]=intval($x['total']);jsonResponse(['status'=>'success','data'=>['contacts'=>$contacts,'conversation_refs'=>$refs,'unread'=>$unread]]);}
    [$ps,$pid]=communicationPartner($_GET['partner']??($input['partner']??''));$params=[$emsId,$ps,$pid,$ps,$pid,$emsId];
    if($ps==='group'){$member=$pdo->prepare("SELECT 1 FROM aurora_chat_group_members WHERE group_id=? AND member_system='ems' AND member_user_id=? AND left_at IS NULL");$member->execute([$pid,$emsId]);if(!$member->fetch())jsonResponse(['status'=>'error','message'=>'Bạn không phải thành viên của nhóm này.'],403);if($route==='/communications/messages'&&$method==='GET'){$q=$pdo->prepare("SELECT m.*,a.id attachment_id,a.original_name,a.mime_type,a.size_bytes,CASE WHEN m.sender_system='tms' THEN tu.full_name ELSE eu.name END sender_name FROM aurora_internal_messages m LEFT JOIN aurora_message_attachments a ON a.message_id=m.id LEFT JOIN users tu ON m.sender_system='tms' AND tu.id=m.sender_user_id LEFT JOIN ems_users eu ON m.sender_system='ems' AND eu.id=m.sender_user_id WHERE m.group_id=? ORDER BY m.id DESC LIMIT 200");$q->execute([$pid]);$rows=array_reverse($q->fetchAll());foreach($rows as &$x){$x['mine']=$x['sender_system']==='ems'&&intval($x['sender_user_id'])===$emsId;$x['attachment']=$x['attachment_id']?['id'=>intval($x['attachment_id']),'name'=>$x['original_name'],'mime'=>$x['mime_type'],'size'=>intval($x['size_bytes'])]:null;$x['reply']=null;$x['reactions']=[];}jsonResponse(['status'=>'success','data'=>$rows]);}if($route==='/communications/read'&&in_array($method,['PUT','POST'])){$q=$pdo->prepare("INSERT INTO aurora_chat_group_reads(group_id,member_system,member_user_id,last_read_message_id,read_at) SELECT ?,'ems',?,COALESCE(MAX(id),0),NOW() FROM aurora_internal_messages WHERE group_id=? ON DUPLICATE KEY UPDATE last_read_message_id=VALUES(last_read_message_id),read_at=NOW()");$q->execute([$pid,$emsId,$pid]);jsonResponse(['status'=>'success']);}if($route==='/communications/messages'&&$method==='POST'){$content=trim((string)($input['content']??''));if($content==='')jsonResponse(['status'=>'error','message'=>'Hãy nhập nội dung tin nhắn.'],422);$q=$pdo->prepare("INSERT INTO aurora_internal_messages(sender_system,sender_user_id,recipient_system,recipient_user_id,group_id,content,topic_tag,message_type,created_at,updated_at) VALUES('ems',?,'group',?,?,?,?,'text',NOW(),NOW())");$q->execute([$emsId,$pid,$pid,$content,substr(trim((string)($input['topic_tag']??'')),0,80)]);$pdo->prepare("UPDATE aurora_chat_groups SET updated_at=NOW() WHERE id=?")->execute([$pid]);jsonResponse(['status'=>'success','data'=>['id'=>intval($pdo->lastInsertId())]],201);}}
    if($route==='/communications/messages'&&$method==='GET'){$sql="SELECT m.*,a.id attachment_id,a.original_name,a.mime_type,a.size_bytes,r.content reply_content,r.message_type reply_message_type,r.sender_system reply_sender_system FROM aurora_internal_messages m LEFT JOIN aurora_message_attachments a ON a.message_id=m.id LEFT JOIN aurora_internal_messages r ON r.id=m.reply_to_id WHERE ".communicationThreadSql()." ORDER BY m.id ASC LIMIT 500";$q=$pdo->prepare($sql);$q->execute($params);$rows=[];$ids=[];foreach($q->fetchAll() as $x){$x['mine']=$x['sender_system']==='ems'&&intval($x['sender_user_id'])===$emsId;$x['attachment']=$x['attachment_id']?['id'=>intval($x['attachment_id']),'name'=>$x['original_name'],'mime'=>$x['mime_type'],'size'=>intval($x['size_bytes'])]:null;$x['reply']=$x['reply_to_id']?['id'=>intval($x['reply_to_id']),'content'=>$x['reply_content'],'type'=>$x['reply_message_type'],'sender_system'=>$x['reply_sender_system']]:null;$x['reactions']=[];$ids[]=intval($x['id']);$rows[intval($x['id'])]=$x;}if($ids){$sql="SELECT message_id,emoji,COUNT(*) total,MAX(actor_system='ems' AND actor_user_id=?) mine FROM aurora_message_reactions WHERE message_id IN (".implode(',',array_fill(0,count($ids),'?')).") GROUP BY message_id,emoji";$q=$pdo->prepare($sql);$q->execute(array_merge([$emsId],$ids));$symbols=array_flip(communicationReactionCodes());foreach($q as $x)$rows[intval($x['message_id'])]['reactions'][]=['emoji'=>$symbols[$x['emoji']]??$x['emoji'],'count'=>intval($x['total']),'mine'=>(bool)$x['mine']];}jsonResponse(['status'=>'success','data'=>array_values($rows)]);}
    if($route==='/communications/read'&&in_array($method,['PUT','POST'])){$q=$pdo->prepare("UPDATE aurora_internal_messages SET read_at=COALESCE(read_at,NOW()),updated_at=NOW() WHERE sender_system=? AND sender_user_id=? AND recipient_system='ems' AND recipient_user_id=?");$q->execute([$ps,$pid,$emsId]);jsonResponse(['status'=>'success']);}
    if($route==='/communications/reactions'&&$method==='POST'){$id=intval($input['message_id']??0);$symbol=(string)($input['emoji']??'');$codes=communicationReactionCodes();if(!isset($codes[$symbol]))jsonResponse(['status'=>'error','message'=>'Cảm xúc không hợp lệ.'],422);$emoji=$codes[$symbol];$q=$pdo->prepare("SELECT m.id FROM aurora_internal_messages m WHERE m.id=? AND ".communicationThreadSql());$q->execute(array_merge([$id],$params));if(!$q->fetch())jsonResponse(['status'=>'error','message'=>'Tin nhắn không thuộc cuộc trò chuyện này.'],404);$q=$pdo->prepare("SELECT 1 FROM aurora_message_reactions WHERE message_id=? AND actor_system='ems' AND actor_user_id=? AND emoji=?");$q->execute([$id,$emsId,$emoji]);if($q->fetch()){$q=$pdo->prepare("DELETE FROM aurora_message_reactions WHERE message_id=? AND actor_system='ems' AND actor_user_id=? AND emoji=?");$q->execute([$id,$emsId,$emoji]);}else{$q=$pdo->prepare("INSERT INTO aurora_message_reactions VALUES(?,'ems',?,?,NOW())");$q->execute([$id,$emsId,$emoji]);}jsonResponse(['status'=>'success']);}
    if($route==='/communications/messages'&&$method==='POST'){$content=trim((string)($input['content']??''));$topic=substr(trim((string)($input['topic_tag']??'')),0,80);$reply=intval($input['reply_to_id']??0);$file=$_FILES['attachment']??null;if($content===''&&!$file)jsonResponse(['status'=>'error','message'=>'Hãy nhập nội dung hoặc chọn một tệp.'],422);if(strlen($content)>4000)jsonResponse(['status'=>'error','message'=>'Tin nhắn không được vượt quá 4.000 ký tự.'],422);$upload=null;if($file){if($file['error']!==UPLOAD_ERR_OK||intval($file['size'])>25*1024*1024)jsonResponse(['status'=>'error','message'=>'Tệp không hợp lệ hoặc vượt quá 25 MB.'],422);$finfo=finfo_open(FILEINFO_MIME_TYPE);$mime=finfo_file($finfo,$file['tmp_name']);finfo_close($finfo);if(in_array($mime,['text/html','image/svg+xml','application/x-php','application/x-msdownload'],true))jsonResponse(['status'=>'error','message'=>'Loại tệp này không được phép.'],422);$dir=communicationUploadDir();if(!is_dir($dir))mkdir($dir,0775,true);$ext=preg_replace('/[^a-z0-9]/','',strtolower(pathinfo($file['name'],PATHINFO_EXTENSION)));$stored=bin2hex(random_bytes(18)).($ext?'.'.$ext:'');if(!move_uploaded_file($file['tmp_name'],$dir.DIRECTORY_SEPARATOR.$stored))jsonResponse(['status'=>'error','message'=>'Không thể lưu tệp.'],500);$upload=['name'=>substr(basename(str_replace('\\','/',$file['name'])),0,255),'stored'=>$stored,'mime'=>$mime,'size'=>intval($file['size']),'type'=>strpos($mime,'image/')===0?'image':(strpos($mime,'audio/')===0?'audio':'file')];}if($reply){$q=$pdo->prepare("SELECT m.id FROM aurora_internal_messages m WHERE m.id=? AND ".communicationThreadSql());$q->execute(array_merge([$reply],$params));if(!$q->fetch())jsonResponse(['status'=>'error','message'=>'Tin nhắn trả lời không hợp lệ.'],422);}$pdo->beginTransaction();try{$q=$pdo->prepare("INSERT INTO aurora_internal_messages(sender_system,sender_user_id,recipient_system,recipient_user_id,content,topic_tag,reply_to_id,message_type,created_at,updated_at) VALUES('ems',?,?,?,?,?,?,?,NOW(),NOW())");$q->execute([$emsId,$ps,$pid,$content,$topic,$reply?:null,$upload?$upload['type']:'text']);$id=intval($pdo->lastInsertId());if($upload){$q=$pdo->prepare("INSERT INTO aurora_message_attachments(message_id,original_name,stored_name,mime_type,size_bytes,created_at) VALUES(?,?,?,?,?,NOW())");$q->execute([$id,$upload['name'],$upload['stored'],$upload['mime'],$upload['size']]);}$pdo->commit();jsonResponse(['status'=>'success','data'=>['id'=>$id]],201);}catch(Throwable $e){$pdo->rollBack();if($upload)@unlink(communicationUploadDir().DIRECTORY_SEPARATOR.$upload['stored']);jsonResponse(['status'=>'error','message'=>'Không thể gửi tin nhắn.'],500);}}
    jsonResponse(['status'=>'error','message'=>'Route trao đổi không tồn tại.'],404);
}
